    h = len(grid)
    w = len(grid[0])

    # Initialize output grid with background color
    new_grid = [[background for _ in range(w)] for _ in range(h)]

    # Apply transformation: Shift non-background pixels diagonal (right 1, down 1)
    for r in range(h):
        for c in range(w):
